import re
import logging
import six

from scrapy.spiders import Spider
from scrapy.http import Request, XmlResponse
from scrapy.utils.sitemap import Sitemap, sitemap_urls_from_robots
from scrapy.utils.gz import gunzip, is_gzipped

logger = logging.getLogger(__name__)


class SitemapSpider(Spider):

    sitemap_urls = ()
    sitemap_rules = [('', 'parse')]
    sitemap_follow = ['']
    sitemap_alternate_links = False

    def __init__(self, *args, **kwargs):
        super(SitemapSpider, self).__init__(*args, **kwargs)
        self._cbs = []
        for rule, callback in self.sitemap_rules:
            if isinstance(callback, six.string_types):
                callback = getattr(self, callback)
            self._cbs.append((regex(rule), callback))
        self._follow = list(map(regex, self.sitemap_follow))

    def start_requests(self):
        requests = [Request(u, self._parse_sitemap) for u in self.sitemap_urls]
        for req in requests:
            yield req

    def _parse_sitemap(self, response):
        if response.url.endswith('/robots.txt'):
            for s_url in sitemap_urls_from_robots(response.body):
                yield Request(s_url, callback=self._parse_sitemap)
        else:
            body = self._get_sitemap_body(response)
            if body is None:
                logger.warning("Ignoring invalid sitemap: %(response)s",
                               {'response': response}, extra={'spider': self})
                return

            sm = Sitemap(body)
            if sm.type == 'sitemapindex':
                for loc in iterloc(sm, self.sitemap_alternate_links):
                    if any(f.search(loc) for f in self._follow):
                        yield Request(loc, callback=self._parse_sitemap)
            elif sm.type == 'urlset':
                for loc in iterloc(sm):
                    for rule, cb in self._cbs:
                        if rule.search(loc):
                            yield Request(loc, callback=cb)
                            break

    def _get_sitemap_body(self, response):
        """Return the sitemap body contained in the given response,
        or None if the response is not a sitemap.
        """
        if isinstance(response, XmlResponse):
            return response.body
        elif is_gzipped(response):
            return gunzip(response.body)
        elif response.url.endswith('.xml'):
            return response.body
        elif response.url.endswith('.xml.gz'):
            return gunzip(response.body)


def regex(x):
    if isinstance(x, six.string_types):
        return re.compile(x)
    return x


def iterloc(it, alt=False):
    for entry in it:
        yield entry['loc']

        # Also consider alternate URLs (xhtml:link rel="alternate")
        if alt and 'alternate' in entry:
            for link in entry['alternate']:
                yield link
